const form = $('On form submission').first().json;
const response = $input.first().json;

const minVram = Number(form.min_vram_gb);
const maxPrice = Number(form.max_price_per_hour);
const gpus = response.gpus ?? [];

const matches = gpus
  .map((gpu) => {
    const lowestPrice = gpu.lowestPrice ?? {};

    const rawPrice =
      lowestPrice.uninterruptablePrice ??
      lowestPrice.uninterruptiblePrice ??
      null;

    const price = rawPrice === null ? null : Number(rawPrice);

    return {
      id: gpu.id,
      name: gpu.displayName ?? gpu.id,
      vram_gb: Number(gpu.memoryInGb ?? 0),
      price_per_hour: Number.isFinite(price) ? price : null,
      stock_status: lowestPrice.stockStatus ?? null,
      available_count: lowestPrice.availableGpuCounts ?? null,
      secure_cloud: gpu.secureCloud ?? false,
      community_cloud: gpu.communityCloud ?? false,
    };
  })
.filter((gpu) =>
  gpu.vram_gb >= minVram &&
  gpu.price_per_hour !== null &&
  gpu.price_per_hour <= maxPrice
)
.sort((a, b) => a.price_per_hour - b.price_per_hour);
return [
  {
    json: {
      criteria: {
        min_vram_gb: minVram,
        max_price_per_hour: maxPrice,
      },
      found: matches.length,
      best_match: matches[0] ?? null,
      matches,
      message:
        matches.length > 0
          ? `Znaleziono ${matches.length} pasujących kart GPU.`
          : `Nie znaleziono GPU spełniającego podane warunki.`,
    },
  },
];

parameters.completionMessage:
={{ $json.found > 0
  ? `Znaleziono ${$json.found} pasujących kart.

Najlepszy wynik:
GPU: ${$json.best_match.name}
VRAM: ${$json.best_match.vram_gb} GB
Cena: ${$json.best_match.price_per_hour} USD/h
Dostępność: ${$json.best_match.stock_status ?? 'brak danych'}`
  : $json.message
}}
